using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using ScreenText;
class CopilotSmoke {
 static string Root=AppDomain.CurrentDomain.BaseDirectory;static BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static T Field<T>(MainForm form,string name){return (T)typeof(MainForm).GetField(name,Flags).GetValue(form);}static object Call(MainForm form,string name,params object[] args){return typeof(MainForm).GetMethod(name,Flags).Invoke(form,args);}
 class Fake:ICopilotRuntime {
  public int Calls,Generations;public bool Fail,Changed;public CopilotCommand Last;
  public Task<CopilotReply> Run(CopilotCommand c,CancellationToken token,Action<string> progress){Calls++;Last=c;token.ThrowIfCancellationRequested();if(Fail)throw new AiConnectionException("Mock quota","copilot_quota");if(Changed&&c.action=="generate")throw new AiConnectionException("Mock account changed","copilot_account_changed");if(c.action=="logout")return Task.FromResult(new CopilotReply());var account=new CopilotSnapshot{authenticated=true,accessChecked=true,catalogLoaded=true,host=c.host,login="fixture-user",models=new List<CopilotModel>{new CopilotModel{id="auto",name="Auto"},new CopilotModel{id="vision-fixture",name="Vision fixture",vision=true}}};if(c.action=="generate"){Check(c.login=="fixture-user","Request did not pin the displayed account");Generations++;if(progress!=null)progress("fixture draft");return Task.FromResult(new CopilotReply{text=c.image==null?"fixture translation":"fixture image text",account=account});}return Task.FromResult(new CopilotReply{account=account});}
 }
 static void Wait(Task task){var start=DateTime.UtcNow;while(!task.IsCompleted){Application.DoEvents();Thread.Sleep(5);if((DateTime.UtcNow-start).TotalSeconds>10)throw new Exception("UI timeout");}task.GetAwaiter().GetResult();}
 static IEnumerable<Control> All(Control control){foreach(Control child in control.Controls){yield return child;foreach(var nested in All(child))yield return nested;}}
 static void Save(Control form,string name){using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,form.Size));image.Save(Path.Combine(Root,name+".png"));}}
 static async Task Service(){var runtime=new Fake();var service=new CopilotConnection(runtime);Check(service.Account==null,"Fresh instance claims a checked account");await service.Check("github.com",false,CancellationToken.None);Check(service.Account.login=="fixture-user"&&runtime.Generations==0,"Status sent inference or identity missing");int before=runtime.Calls;try{await service.Generate("company.ghe.com","auto","fixture",null,CancellationToken.None,null);throw new Exception("Cross-host request accepted");}catch(AiConnectionException){}Check(runtime.Calls==before,"Cross-host request reached runtime");Check(await service.Generate("github.com","auto","fixture",null,CancellationToken.None,null)=="fixture translation","Translation route failed");Check(await service.Generate("github.com","vision-fixture","fixture",new byte[]{1},CancellationToken.None,null)=="fixture image text"&&runtime.Last.image!=null,"Image route failed");runtime.Fail=true;try{await service.Generate("github.com","auto","fixture",null,CancellationToken.None,null);throw new Exception("Expected quota");}catch(AiConnectionException){}Check(service.Account!=null,"Quota failure signed out");runtime.Fail=false;runtime.Changed=true;try{await service.Generate("github.com","auto","fixture",null,CancellationToken.None,null);throw new Exception("Expected account mismatch");}catch(AiConnectionException){}Check(service.Account==null,"Changed account remains eligible");runtime.Changed=false;await service.Check("company.ghe.com",true,CancellationToken.None);await service.SignOut("company.ghe.com","fixture-user",CancellationToken.None);Check(service.Account==null&&runtime.Last.host=="company.ghe.com"&&runtime.Last.login=="fixture-user","Logout not bound to shown account");int calls=runtime.Calls;try{await service.Check("company.ghe.com.evil.test",true,CancellationToken.None);}catch(ArgumentException){}Check(runtime.Calls==calls,"Bad host reached runtime");var canceled=new CancellationToken(true);try{await service.Check("github.com",false,canceled);}catch(OperationCanceledException){}Check(runtime.Calls==calls,"Canceled action reached runtime");}
 static void Ui(){using(var form=new MainForm(true)){form.Show();Application.DoEvents();var runtime=new Fake();var service=new CopilotConnection(runtime);typeof(MainForm).GetField("copilot",Flags).SetValue(form,service);var prefs=Field<AiPreferences>(form,"aiPreferences");string translation=prefs.TranslationModel,extraction=prefs.ExtractionModel;var provider=Field<ThemeCombo>(form,"aiSettingsProvider");provider.SelectedIndex=1;Call(form,"SelectSettingsCategory","AI Providers");Call(form,"ShowAiTab",false);var window=Field<Form>(form,"settingsWindow");window.Show(form);Application.DoEvents();Check(runtime.Calls==0,"Browsing settings connected");Check(Field<Button>(form,"providerConnectionButton").Text=="Sign in","Browsing changed active provider");Wait(service.Check("github.com",false,CancellationToken.None));Call(form,"UpdateAiControls");Check(Field<Label>(form,"copilotIdentity").Text.Contains("fixture-user"),"Identity missing");Call(form,"UseAiProvider",true);Check(Field<Button>(form,"providerConnectionButton").Text=="GitHub Copilot","Active provider chip missing");Check(((AccountChip)Field<Button>(form,"providerConnectionButton")).Subtitle.Contains("fixture-user"),"Header account missing");
  var source=Field<TextBox>(form,"source");source.Text="Hello fixture";Wait((Task)Call(form,"Translate","el","Greek"));Check(Field<TextBox>(form,"result").Text=="fixture translation"&&runtime.Last.model=="auto","Workspace translation used wrong provider/model");using(var timer=new System.Windows.Forms.Timer{Interval=80}){timer.Tick+=(sender,eventArgs)=>{foreach(Form dialog in Application.OpenForms)if(dialog.Text=="Translate to"&&dialog.Modal){var controls=All(dialog).ToList();controls.OfType<TextBox>().First(t=>t.AccessibleName=="Search translation language").Text="Japanese";var button=controls.OfType<Button>().First(b=>b.Text=="Translate");typeof(Button).GetMethod("OnClick",Flags).Invoke(button,new object[]{EventArgs.Empty});timer.Stop();break;}};timer.Start();Wait((Task)Call(form,"ChooseTranslationLanguage"));}Check(Field<Label>(form,"resultTitle").Text.Contains("Japanese"),"Copilot More did not translate selected target");var cp=Field<CopilotPreferences>(form,"copilotPreferences");cp.TranslationModel="missing-fixture";Call(form,"UpdateAiControls");Check(Field<Label>(form,"aiModelNotice").Visible&&Field<ThemeCombo>(form,"copilotTranslationModel").Text.Contains("Unverified"),"Missing Copilot model warning lost");cp.TranslationModel="auto";Call(form,"UpdateAiControls");var model=Field<ThemeCombo>(form,"workspaceTranslationModel");model.SelectedIndex=1;Check(Field<CopilotPreferences>(form,"copilotPreferences").TranslationModel=="vision-fixture"&&prefs.TranslationModel==translation&&prefs.ExtractionModel==extraction,"Model selections leaked to ChatGPT");
  foreach(int mode in new[]{0,1}){Field<ThemeCombo>(form,"themeChoice").SelectedIndex=mode;Call(form,"ShowAiTab",false);Application.DoEvents();Save(window,"Copilot-account-"+mode);Call(form,"ShowAiTab",true);Application.DoEvents();Save(window,"Copilot-models-"+mode);window.Hide();Save(form,"Copilot-workspace-"+mode);window.Show(form);}
  provider.SelectedIndex=0;Call(form,"ShowAiTab",false);Check(Field<RoundedPanel>(form,"aiDirectSection").Visible,"ChatGPT settings lost");Check(Field<Button>(form,"providerConnectionButton").Text=="GitHub Copilot","Browsing ChatGPT changed routing");Call(form,"UseAiProvider",false);Check(Field<TextBox>(form,"result").Text=="fixture translation","Provider switch erased text");Check(prefs.TranslationModel==translation&&prefs.ExtractionModel==extraction,"ChatGPT preferences changed");window.Hide();Call(form,"ExitApplication");}}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Service().GetAwaiter().GetResult();Ui();File.WriteAllText(args[0],"PASS: explicit provider routing; CLI account pinning; public/Enterprise host validation; separate model selections; text/image SDK commands; quota preserves connection; changed account blocks further requests; per-account logout command; cancellation; browsing does not connect/switch; retained text and ChatGPT defaults; dark/light previews. Mock adapter only, no real account or inference.");return 0;}catch(Exception ex){File.WriteAllText(args[0],ex.ToString());return 1;}}
